122	        if let Some(complex) = self.downcast_ref::<PyComplex>() {
123	            return Ok(Some((complex.value, true)));
124	        }
125	        if let Some(float) = self.try_float_opt(vm) {
126	            return Ok(Some((Complex64::new(float?.to_f64(), 0.0), false)));
127	        }
128	        Ok(None)
129	    }
